import { rateLimitCleanup } from "@/lib/rate-limit-jobs";
import { serve } from "inngest/next";
import {
  inngest,
  sendEmail,
  maintenance,
  accountMaintenance,
  quotaReconciliation,
} from "@/lib/inngest";
import { deletionJobSweep, deletionJobWorker } from "@/lib/lifecycle-jobs";
import { billingMaintenance } from "@/lib/billing/schedules";
export const maxDuration = 300;
export const { GET, POST, PUT } = serve({
  client: inngest,
  functions: [
    rateLimitCleanup,
    sendEmail,
    deletionJobSweep,
    deletionJobWorker,
    maintenance,
    accountMaintenance,
    quotaReconciliation,
    billingMaintenance,
  ],
});
